import ast
src = open("calc.py").read()
for n in ast.walk(ast.parse(src)):
    if isinstance(n, ast.FunctionDef):
        args = [a.arg for a in n.args.args]
        assigned = {t.id for s in ast.walk(n) if isinstance(s, ast.Assign) for t in s.targets if isinstance(t, ast.Name)}
        assert not (args == ["a", "b"] and "c" in assigned), "names unchanged"
from calc import f
for a, b in [(3,4),(0,5),(-2,7),(1.5,2),(10**12,3),("ab",3),([1],2)]:
    assert f(a, b) == a * b, (a, b)
print("ok")
